export const BODY: string = "\n<p>كل GIF مساومة بين السلاسة والحجم. معدل إطارات أعلى يجعل الحركة ناعمة، لكنه يجعل الملف أكبر أيضًا. وملف أصغر يُشارك أسرع، لكنه قد يبدو متقطعًا.</p>\n<p>يشرح هذا الدليل الأشياء الأربعة التي تقرر حجم ملف GIF: معدل الإطارات وعدد الإطارات والأبعاد ولوحة الألوان. ويعرض كيف يوازن كل منها مع السلاسة، وكيف تصغّر ملفًا كبيرًا جدًا.</p>\n<p>كل الأدوات الموصوفة هنا تعيش في <a href=\"/ar/munshi-gif/\">صانع GIF</a>. تحدد معدل الإطارات وعدد الإطارات وحجم الإخراج قبل التوليد، وتحذرك الأداة عندما يتجاوز الملف المقدر حدود المشاركة.</p>\n<h2 id=\"frame-rate-vs-file-size\">معدل الإطارات مقابل حجم الملف</h2>\n<p>معدل الإطارات هو عدد الإطارات التي تُعرض في الثانية، وهو أكثر مقايضة مباشرة عند صنع GIF. إطارات أكثر في الثانية تعني حركة أنعم، لأن العين ترى خطوات أصغر بين المواضع.</p>\n<p>GIF بإطار واحد في الثانية عرض شرائح: كل صورة تبقى ثانية كاملة، والحركة سلسلة قفزات. وGIF بعشرة إطارات في الثانية ناعم بما يكفي لمعظم المواضيع. والعلاقة خطية تقريبًا: مضاعفة معدل الإطارات تضاعف عدد الإطارات في الثانية، ويكبر حجم الملف بنسبة مماثلة.</p>\n<h2 id=\"how-gif-compression-works\">كيف يعمل ضغط GIF</h2>\n<p>ضغط GIF يعمل بحفظ البكسلات التي تتغير بين الإطارات فقط. إذا كان إطاران متطابقين إلا جسم صغير متحرك، يحفظ المرمّز الإطار الأول كاملًا ثم يحفظ فقط المنطقة المتغيرة في الإطار التالي.</p>\n<p>GIF لمشهد يتحرك فيه كل شيء يضغط بشكل سيئ، لأن كل بكسل تقريبًا يتغير في كل إطار. وتحريك كاميرا عبر منظر طبيعي أو تغيير لون في الشاشة كلها يهزم الضغط. ولوحة 256 لونًا هي الحد الآخر: كل إطار يستطيع استخدام 256 لونًا كحد أقصى، فيختار المرمّز الألوان الأهم.</p>\n<h2 id=\"frames-per-second-choices\">خيارات الإطارات في الثانية</h2>\n<p>إطار واحد في الثانية يناسب عرضًا حيث تستحق كل صورة نظرة كاملة. مجموعة صور معروضة صورة في الثانية تُقرأ كتسلسل متعمد، والملف يبقى صغيرًا.</p>\n<p>إطاران في الثانية يناسبان عرضًا بطيئًا، مثل عملية خطوة بخطوة حيث يحتاج كل خطوة نصف ثانية لتُسجل. وخمسة إطارات في الثانية هي النقطة المثالية لمعظم GIF: سريعة بما يكفي لتبدو كحركة وبطيئة بما يكفي ليسجل كل إطار. وعشرة إطارات في الثانية هي أنعم ما تقدمه الأداة.</p>\n<h2 id=\"frame-count\">عدد الإطارات</h2>\n<p>عدد الإطارات هو العدد الإجمالي للصور في GIF، ويتضاعف مع المعدل ليقرر المدة. GIF فيه خمسة عشر إطارًا بخمسة إطارات في الثانية يدوم ثلاث ثوانٍ.</p>\n<p>القصيرة هي الأفضل. حركة ثلاث ثوانٍ تقول ما لديها أكثر فعالية من عشر ثوانٍ تتكرر. وقلّص قائمة الإطارات إلى اللحظات الأساسية وسيتقلص GIF معها. وكل إطار تزيله توفير مباشر: بخلاف المعدل الذي هو مقايضة مع السلاسة، قص إطار زائد لا يكلف شيئًا في الجودة.</p>\n<h2 id=\"output-dimensions\">أبعاد الإخراج</h2>\n<p>الأبعاد هي أكبر رافعة على حجم الملف. تقليل عرض الإخراج إلى النصف يقطع عدد البكسلات إلى الربع، لأن العرض والارتفاع يتصغران معًا.</p>\n<p>GIF بعرض 480 بكسل هو المعيار للمحادثة والمشاركة الاجتماعية: كبير بما يكفي ليُرى بوضوح على هاتف وصغير بما يكفي ليُرسل بسرعة. وGIF بعرض 960 بكسل فيه أربعة أضعاف البكسلات وعدة أضعاف حجم الملف، لفرق لن يلاحظه معظم الناس.</p>\n<h2 id=\"color-palette-and-size\">لوحة الألوان والحجم</h2>\n<p>لوحة الألوان تؤثر في الجودة والحجم معًا. GIF يستطيع حفظ 256 لونًا كحد أقصى في الإطار، والمرمّز يختار أي الألوان يحتفظ بها. والتحكم في جودة اللوحة يقرر مدى عناية ذلك الاختيار.</p>\n<p>جودة لوحة أعلى تحلل الإطارات بتفصيل أكبر وتحافظ على الألوان الأهم. تعطي تدرجات أنعم ودرجات بشرة أدق، لكنها تستغرق وقتًا أطول في الترميز وقد تنتج ملفًا أكبر قليلًا. وجودة لوحة أقل ترمّز أسرع وتعطي ملفات أصغر، لكن التدرجات قد تظهر خطوطًا والألوان الخفيفة قد تتغير.</p>\n<h2 id=\"transparency-cost\">تكلفة الشفافية</h2>\n<p>الشفافية في GIF لون شفاف واحد لا قناة ألفا ناعمة. البكسل إما شفاف تمامًا أو معتم تمامًا، فالحواف الناعمة تصبح صلبة والظلال تختفي.</p>\n<p>GIF شفاف قد يكون أكبر من معتم، لأن المناطق الشفافة تحتاج ترميزًا أيضًا والحواف الصلبة تضغط بكفاءة أقل من التدرجات الناعمة. والحواف الناعمة هي المشكلة الرئيسية: شعار بحافة مموّهة أو ظل يظهر هالة عندما تُجبر البكسلات شبه الشفافة على أن تصبح صلبة أو شفافة.</p>\n<h2 id=\"loop-count-and-size\">عدد التكرارات والحجم</h2>\n<p>عدد التكرارات لا يغيّر حجم الملف. GIF يتكرر إلى الأبد وآخر يُعرض مرة واحدة يحتويان الإطارات نفسها، فالملف له الحجم نفسه في الحالتين.</p>\n<p>وهذا يجعل التكرار اختيارًا مجانيًا. حلقة لا نهائية لا تكلف شيئًا في حجم الملف، وعرض واحد لا يوفر شيئًا. اختر التكرار حسب السياق والشخص الذي سيشاهده. لكن التكرار يؤثر في تجربة الحجم: GIF كبير يتكرر إلى الأبد يجعل الشخص ينتظر أثناء التنزيل ثم يتكرر، ما يبدو ثقيلًا.</p>\n<h2 id=\"when-a-gif-beats-a-video\">متى يتفوق GIF على الفيديو</h2>\n<p>يتفوق GIF على الفيديو عندما تكون الحركة قصيرة وصامتة وتحتاج إلى التشغيل دون مشغل. رد فعل أو دوران منتج لثانيتين أو خطوة تعليمية تُعرض فورًا أينما لُصقت.</p>\n<p>كما تتفوق GIF في المحادثات والتعليقات، حيث الصيغة أصلية. GIF ملصوق في محادثة يتحرك داخل السطر، بينما الفيديو قد يظهر كرابط أو صورة مصغرة تحتاج نقرة. والحلقات القصيرة هي أرض GIF الخاصة: حركة أقل من خمس ثوانٍ بحركة بسيطة وإطارات قليلة هي GIF.</p>\n<h2 id=\"when-a-video-beats-a-gif\">متى يتفوق الفيديو على GIF</h2>\n<p>يتفوق الفيديو على GIF عندما تكون الحركة طويلة أو مفصلة أو ملونة. مقطع عشر ثوانٍ بحركة ملونة كاملة جزء صغير من الحجم كـMP4 مقارنة بـGIF، لأن ضغط الفيديو أقوى بكثير.</p>\n<p>كما يتفوق الفيديو في الحركة الناعمة. GIF يصل إلى عشرة إطارات في الثانية كحد أقصى في هذه الأداة، بينما الفيديو يُعرض بثلاثين أو ستين. والصوت هو ميزة الفيديو الواضحة: GIF صامت بالتعريف، فأي حركة تحتاج سردًا أو موسيقى أو مؤثرات صوتية يجب أن تكون فيديو.</p>\n<h2 id=\"shrinking-a-finished-gif\">كيف تصغّر GIF مكتملًا</h2>\n<p>GIF مكتمل كبير جدًا يمكن تصغيره بعدها. <a href=\"/ar/daght-gif/\">ضاغط GIF</a> يقلل الملف بتحسين الإطارات واللوحة، ما قد يقطع الحجم بشكل كبير إذا كانت الإطارات متكررة والألوان بسيطة.</p>\n<p>الضغط يعمل أفضل في GIF ذات الإطارات الزائدة والألوان البسيطة. وإعادة التوليد من الإطارات أفضل غالبًا من ضغط الملف المكتمل، لأن الإطارات تتيح قص العدد وتصغير الأبعاد وخفض المعدل، وهي توفيرات أكبر من أي تحسين لاحق. وعندما يجب تصغير GIF لم تصنعه أنت، يكون الضغط هو الخيار الوحيد.</p>\n<h2 id=\"the-smooth-vs-small-decision\">القرار بين الناعم والصغير</h2>\n<p>القرار مسألة جمهور وسياق. GIF لرسالة محادثة يجب أن يكون صغيرًا، لأنه يُشارك عبر بيانات الجوال ويُعرض على هاتف. السلاسة تهم أقل من سرعة التحميل.</p>\n<p>أما GIF لموقع أو عرض تقديمي فيمكن أن يكون أكبر، لأن الشخص على اتصال مستقر وشاشة أكبر. والسلاسة تهم أكثر هناك، لأن الحركة جزء من العرض. وابدأ بخمسة إطارات في الثانية وعرض 480 بكسل، ثم اضبط: إذا بدت الحركة متقطعة فارفع المعدل إلى عشرة، وإذا كان الملف كبيرًا جدًا فاخفض العرض أولًا.</p>\n<h2 id=\"quick-reference\">مرجع سريع: الناعم مقابل الصغير</h2>\n<p>خمسة إطارات في الثانية وعرض 480 بكسل هو القيمة المتوازنة الافتراضية. عشرة إطارات في الثانية تشتري سلاسة بضعف الإطارات، وتقليل العرض إلى النصف يقلل البكسلات إلى الربع.</p>\n<p>عدد التكرارات لا يؤثر في حجم الملف. الشفافية تكلف قليلًا وتحتاج حوافًا صلبة. وعندما يتجاوز GIF 15 ميغابايت ولا يساعد أي قص، استخدم فيديو.</p>\n<p>للإنشاء خطوة بخطوة، اقرأ <a href=\"/ar/blog/kayfiyya-ins-ha-gif-min-as-suwar/\">كيف تنشئ GIF من صور</a>، وللدليل الكامل اقرأ <a href=\"/ar/blog/dalil-munshi-gif/\">صانع GIF: الدليل الكامل</a>. وأنشئ GIF مع <a href=\"/ar/munshi-gif/\">صانع GIF</a>، وصغّر مكتملًا مع <a href=\"/ar/daght-gif/\">ضاغط GIF</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"أي معدل إطارات أستخدم لـGIF؟","answer":"خمسة إطارات في الثانية هي أفضل قيمة افتراضية لمعظم GIF: سريعة بما يكفي لتبدو كحركة وبطيئة بما يكفي ليبقى الملف صغيرًا. واستخدم إطارًا أو إطارين في الثانية للعروض البطيئة، وعشرة للحركة التي يجب أن تبدو ناعمة."},{"question":"هل معدل إطارات أعلى يبدو أفضل دائمًا؟","answer":"لا، فالقفزة من إطار إلى خمسة إطارات في الثانية درامية، لكن القفزة من خمسة إلى عشرة خفيفة لمعظم المواضيع، بينما يتضاعف حجم الملف. وبعد عشرة إطارات في الثانية، تقل العوائد بينما يستمر الحجم في النمو."},{"question":"كم يزيد حجم الملف عند مضاعفة المعدل؟","answer":"نحو الضعف، لأن مضاعفة المعدل تضاعف عدد الإطارات في الثانية. GIF ثلاث ثوانٍ بخمسة إطارات في الثانية فيه خمسة عشر إطارًا؛ ونفس GIF بعشرة إطارات في الثانية فيه ثلاثون إطارًا وحجمه ضعف تقريبًا."},{"question":"ما أصغر حجم ملف يمكنني توقعه لـGIF؟","answer":"لا حد أدنى ثابت، لأن الحجم يعتمد على الإطارات والأبعاد والألوان. GIF قصير بإطارات قليلة وعرض 480 بكسل وألوان مسطحة قد يكون أقل بكثير من ميغابايت. أما GIF طويل بأبعاد كبيرة وصور فوتوغرافية فقد يتجاوز 15 ميغابايت."},{"question":"هل يؤثر عدد التكرارات في حجم GIF؟","answer":"لا، فـGIF يتكرر إلى الأبد وآخر يُعرض مرة واحدة يحتويان الإطارات نفسها، فالملف له الحجم نفسه في الحالتين. إعداد التكرار يغيّر فقط كيف يتصرف التشغيل لا حجم الملف."},{"question":"هل الأفضل تقليل الإطارات أم تقليل الأبعاد لتصغير GIF؟","answer":"قلل الأبعاد أولًا، لأن تقليل العرض إلى النصف يقطع البكسلات إلى الربع، وهو أكبر توفير منفرد. ثم قص الإطارات الزائدة، فهذا لا يكلف شيئًا في الجودة. واخفض المعدل أخيرًا إذا بقي الملف كبيرًا."}];
